// step-reader-test (#1695): the STEP path of the viewer, outside the device. A tiny STEP generated by step-fixture.mjs is read by the SAME
// occt-import-js and tess.js the page worker (libs:cad-brep worker.js) runs; RED unless it yields one GLB node per solid, with the solid's name and
// colour and 12 triangles per box, and the GLB parses (header, JSON, BIN). Mutants prove the checks bite. Usage: node step-reader-test.mjs <repo root>
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import vm from 'node:vm';
import { stepBoxes } from './step-fixture.mjs';
const root = process.argv[2] || '../..';
const brep = `${root}/ab_cloud-libs-shared/libs/cad-brep/src/main/assets/cad/brep`;
const ctx = { TextEncoder, Float32Array, Uint32Array, Uint8Array, DataView, Math, JSON, Error, String }; ctx.self = ctx;
vm.runInNewContext(readFileSync(`${brep}/tess.js`, 'utf8'), ctx);
const tess = ctx.brepTess;
const occt = await createRequire(import.meta.url)(`${brep}/vendor/occt-import-js.js`)();
let fails = 0; const ok = (c, m) => { console.log((c ? '  PASS: ' : '  FAIL: ') + m); if (!c) fails++; };
function glbJson(u8) {
  const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
  if (dv.getUint32(0, true) !== 0x46546c67 || dv.getUint32(4, true) !== 2 || dv.getUint32(8, true) !== u8.length) throw new Error('bad GLB header');
  const jl = dv.getUint32(12, true); if (dv.getUint32(16, true) !== 0x4e4f534a) throw new Error('no JSON chunk');
  const j = JSON.parse(new TextDecoder().decode(u8.subarray(20, 20 + jl)));
  const bl = dv.getUint32(20 + jl, true); if (dv.getUint32(24 + jl, true) !== 0x004e4942) throw new Error('no BIN chunk');
  for (const v of j.bufferViews) if (v.byteOffset + v.byteLength > bl) throw new Error('buffer view outside BIN');
  return j;
}
function check(text, label) {
  const steps = []; const r = tess.read(occt, new TextEncoder().encode(text), 'step', (t) => steps.push(t));
  const j = glbJson(r.glb); const named = j.nodes.filter((n) => n.mesh !== undefined);
  return { r, j, named, steps };
}
console.log('[step reader] generated fixture through occt-import-js + tess.js');
const { r, j, named, steps } = check(stepBoxes(), 'real');
ok(named.length === 2, `one GLB node per solid (${named.length})`);
ok(new Set(named.map((n) => n.name)).size === 2 && named.every((n) => n.name.startsWith('fixture')), `every solid is named from the file's product, uniquely (${named.map((n) => n.name)})`);
ok(r.parts.every((p) => p.triangles === 12), `12 triangles per box (${r.parts.map((p) => p.triangles)})`);
const rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
ok(new Set(r.parts.map((p) => p.color)).size === 2 && r.parts.some((p) => { const c = rgb(p.color); return c[0] > 4 * c[1] && c[0] > 4 * c[2]; }), `each solid keeps its own colour, the red box red (${r.parts.map((p) => p.color)})`);
ok(j.materials.every((m) => m.doubleSided && m.pbrMetallicRoughness.baseColorFactor[3] === 1 && !m.alphaMode), 'materials are opaque and double-sided');
ok(steps.length >= 2, `progress is reported (${steps.length} stages)`);
ok(!tess.yUp(new TextEncoder().encode(stepBoxes()), 'step') && tess.yUp(new TextEncoder().encode("ISO-10303-21;\nHEADER;\nFILE_NAME('a','',(''),(''),'SwSTEP 2.0','SolidWorks 2015','');\nENDSEC;\nDATA;\n"), 'step'), 'a SolidWorks STEP is read Y-up, the others Z-up');
// mutants: a checker that cannot fail is not one
let red = 0;
try { check('ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\nENDSEC;\nEND-ISO-10303-21;\n', 'empty'); } catch (e) { red++; }
ok(red === 1, 'an empty STEP is refused with a reason');
const one = check(stepBoxes([{ name: 'Only', min: [0, 0, 0], max: [1, 1, 1], rgb: [0, 0, 1] }]));
ok(one.named.length === 1 && one.named[0].name === 'fixture', `a one-solid file yields exactly one node, named after its product (${one.named.map((n) => n.name)})`);
let bad = 0; const cut = r.glb.slice(0, r.glb.length - 8); try { glbJson(cut); } catch (e) { bad++; }
ok(bad === 1, 'a truncated GLB does not parse');
if (fails) { console.error(fails + ' failure(s)'); process.exit(1); }
console.log('ALL GREEN');
